INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (110, 'Green Heron at the same spot as last week. Waits without moving, then strikes downward at a fish.', 1776180736, 1, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (111, 'Saw a Boat-billed Heron at the harbour this morning. Hunts alone along the edge of the water.', 1776183084, 6, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (112, 'Came across a Goliath Heron on the canal path. Roosts in trees, often with others of its kind.', 1776184251, 4, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (113, 'Squacco Heron in the creek at low tide. Roosts in trees, often with others of its kind.', 1776209430, 4, 'MSTSNM:Arter:c68811f4-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (114, 'Came across a Least Bittern on the canal path. Heard far more often than it is seen.', 1776213008, 2, 'MSTSNM:Arter:f54eddf8-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (115, 'Several Eurasian Spoonbills feeding together at the lagoon. Feeds by touch rather than sight.', 1776267060, 1, 'MSTSNM:Arter:f3fa2bf9-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (116, 'A American White Pelican by the reeds at the lake. Very large bird with a long bill and a stretchy throat pouch.', 1776327571, 2, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (117, 'Saw a Hamerkop at the harbour this morning. Feeds on frogs and small fish in shallow water.', 1776386469, 5, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (118, 'Four Black Herons out on the sandbar this morning. Tall bird that stands still in shallow water for long stretches.', 1776425670, 3, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (119, 'A Scarlet Ibis in the shallows near the boat ramp. The plumage looks black until the sun catches it.', 1776471370, 2, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (120, 'Four Great Egrets out on the sandbar this morning. Black legs with contrasting pale feet.', 1776522779, 5, 'MSTSNM:Arter:c18811f4-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (121, 'One American White Ibis at the estuary at dusk. Nests in colonies, often alongside herons.', 1776523362, 6, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (122, 'A American White Pelican by the sluice gate. Heavy on land but glides well once airborne.', 1776786986, 7, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (123, 'The American White Ibises are back on the lake. Long, downcurved bill used to probe soft ground.', 1776874031, 5, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (124, 'Found a Northern Bald Ibis in the marsh behind the dunes. Bare skin on the face and head.', 1776896798, 6, 'MSTSNM:Arter:4b50c87f-f904-4fc0-8bb4-b0b500cd367d');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (125, 'Three Great White Pelicans in the shallows by the hide. Pale body with dark wingtips, easy to pick out in flight.', 1776942864, 2, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (126, 'A Squacco Heron resting on a sandbank. Walks very slowly through the shallows while hunting.', 1777066427, 6, 'MSTSNM:Arter:c68811f4-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (127, 'Saw a Snowy Egret at the harbour this morning. Moves quickly through the water when chasing fish.', 1777067973, 4, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (128, 'One Great Egret on the flooded field after the rain. Grows fine plumes on the back in the breeding season.', 1777113670, 4, 'MSTSNM:Arter:c18811f4-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (129, 'A Western Reef Egret wading through the reed bed. Grows fine plumes on the back in the breeding season.', 1777138529, 6, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (130, 'A Snowy Egret wading through the reed bed. Stirs the mud with one foot to move prey into the open.', 1777150026, 2, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (131, 'Three Little Egrets in the shallows by the hide. Slimmer and lighter than a heron.', 1777159797, 7, 'MSTSNM:Arter:ca4d8cf8-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (132, 'One Peruvian Pelican out on the mudflat. Scoops fish out of the water with the pouch, then drains it.', 1777199681, 4, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (133, 'A Eurasian Bittern by the sluice gate. Stays within cover almost all the time.', 1777223705, 7, 'MSTSNM:Arter:2d9011f4-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (134, 'Found a Green Heron in the marsh behind the dunes. Flies with the neck folded back against the body.', 1777296466, 4, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (135, 'A Northern Bald Ibis wading through the reed bed. Feeds in flocks on wet ground.', 1777325399, 7, 'MSTSNM:Arter:4b50c87f-f904-4fc0-8bb4-b0b500cd367d');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (136, 'A Roseate Spoonbill perched in a tree above the water. White bird with a flat bill shaped like a spoon.', 1777348513, 7, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (137, 'A Brown Pelican wading through the reed bed. Swims on the surface and dips the head under to feed.', 1777369185, 2, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (138, 'A Eurasian Bittern resting on a sandbank. Stays within cover almost all the time.', 1777383776, 5, 'MSTSNM:Arter:2d9011f4-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (139, 'Came across a Eurasian Spoonbill on the canal path. Wades slowly, usually with others nearby.', 1777390888, 3, 'MSTSNM:Arter:f3fa2bf9-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (140, 'A group of Glossy Ibises on the flooded field. Flies in loose lines with the neck held out.', 1777500480, 3, 'MSTSNM:Arter:3efc2bf9-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (141, 'Found a Peruvian Pelican in the marsh behind the dunes. Heavy on land but glides well once airborne.', 1777547275, 5, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (142, 'One Sacred Ibis out on the mudflat. Walks steadily across grass while feeding.', 1777559554, 5, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (143, 'Peruvian Pelican on the pond at the edge of town. Heavy on land but glides well once airborne.', 1777586315, 3, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (144, 'Six Hamerkops along the breakwater. Feeds on frogs and small fish in shallow water.', 1777719792, 1, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (145, 'A Western Reef Egret in the ditch beside the road. Nests in colonies, often in trees near water.', 1777721347, 3, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (146, 'Three Black Herons in the shallows by the hide. Slow, deep wingbeats in flight.', 1777739890, 3, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (147, 'A Northern Bald Ibis standing on the jetty. Flies in loose lines with the neck held out.', 1777754432, 2, 'MSTSNM:Arter:4b50c87f-f904-4fc0-8bb4-b0b500cd367d');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (148, 'Four Snowy Egrets out on the sandbar this morning. White bird with long legs, wading in the shallows.', 1777834726, 1, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (149, 'The Black-faced Spoonbills are back on the lake. Rests with the bill tucked into the back feathers.', 1777888339, 3, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (150, 'A Sacred Ibis in the ditch beside the road. Bare skin on the face and head.', 1777975338, 1, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (151, 'Found a Least Bittern in the marsh behind the dunes. Heard far more often than it is seen.', 1778104190, 4, 'MSTSNM:Arter:f54eddf8-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (152, 'Found a Squacco Heron in the marsh behind the dunes. Walks very slowly through the shallows while hunting.', 1778115046, 4, 'MSTSNM:Arter:c68811f4-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (153, 'Saw a Peruvian Pelican from the train, near the wetlands. Pale body with dark wingtips, easy to pick out in flight.', 1778155751, 4, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (154, 'Saw a American White Pelican at the harbour this morning. Flies in a line, low over the surface.', 1778167725, 4, NULL);
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (155, 'A Eurasian Bittern feeding along the shoreline. Moves along the reed edge, mostly at dawn and dusk.', 1778193237, 2, 'MSTSNM:Arter:2d9011f4-f785-ea11-aa77-501ac539d1ea');
INSERT INTO observation (observation_id, text, timestamp, author_id, taxon_id) VALUES (156, 'A Least Bittern in the ditch beside the road. Hard to see even at close range.', 1778217950, 4, 'MSTSNM:Arter:f54eddf8-f785-ea11-aa77-501ac539d1ea');
